package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;

import org.junit.jupiter.api.Test;

class LmdbNativeSnapshotForcingTest {

	@Test
	void aPreferenceListDoesNotMarkItsSelectedFamilyImpossible() {
		NativeAggregateCostQuotes.Snapshot snapshot = snapshot("nestedLoop,irKernel");
		assertThat(snapshot.canAttempt("nestedLoop")).isTrue();
	}

	@Test
	void anExactRequestedVariantRemainsPossibleWithoutAdmittingItsSibling() {
		NativeAggregateCostQuotes.Snapshot snapshot = snapshot("nestedLoop(fullValue)");
		assertThat(snapshot.canAttempt("nestedLoop(fullValue)")).isTrue();
		assertThat(snapshot.canAttempt("nestedLoop")).isFalse();
		assertThat(snapshot.canAttempt("nestedLoop(autoChild)")).isFalse();
	}

	@Test
	void aBareFamilyStillAllowsItsVariantsAndExcludesOtherFamilies() {
		NativeAggregateCostQuotes.Snapshot snapshot = snapshot("nestedLoop");
		assertThat(snapshot.canAttempt("nestedLoop(fullValue)")).isTrue();
		assertThat(snapshot.canAttempt("irAggregateInterpreted")).isFalse();
	}

	@Test
	void anUnforcedSnapshotKeepsEveryQuotedCandidatePossible() {
		NativeAggregateCostQuotes.Snapshot snapshot = snapshot(null);
		assertThat(snapshot.canAttempt("nestedLoop")).isTrue();
		assertThat(snapshot.canAttempt("orderedDistinctGroups")).isTrue();
	}

	private static NativeAggregateCostQuotes.Snapshot snapshot(String forced) {
		return new NativeAggregateCostQuotes.Snapshot(List.of(), 0L, forced);
	}
}
